<!-- 原型: A1 公开名片 / A4 停用 / A5 微信引导 -->
<script setup lang="ts">
import { computed, onUnmounted, shallowRef, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { createVisit, publicCard, updateVisit } from '@/api/generated'
import DemoBadge from '@/components/common/DemoBadge.vue'
import ResourceState from '@/components/common/ResourceState.vue'
import CardAiEntry from '@/components/visitor/CardAiEntry.vue'
import CardDetails from '@/components/visitor/CardDetails.vue'
import CardHero from '@/components/visitor/CardHero.vue'
import DisabledCard from '@/components/visitor/DisabledCard.vue'
import { useResource } from '@/composables/useResource'
import { callPhone, copyText, isWechat, openMap, saveContact } from '@/platform'
import { useVisitorStore } from '@/stores/visitor'
import { sceneCampaign, sceneKey, sceneQuery, sceneSource } from '@/utils/scene'
const route = useRoute('/card/[code]'); const router = useRouter(); const visitor = useVisitorStore()
const code = computed(() => String(route.params.code))
const origin = window.location.origin
const eventId = computed(() => sceneCampaign(route.query.e))
const activeSource = computed(() => sceneSource(route.query.s))
const shareQuery = computed(() => `s=${activeSource.value}${eventId.value ? `&e=${eventId.value}` : ''}`)
const guide = shallowRef(false); const wechat = shallowRef(false); const trackingError = shallowRef('')
let visitId: number | undefined; let visitRevision = 0; let started = Date.now()
const { data: card, loading, error, reload } = useResource(async () => {
 const result = await publicCard({ path: { code: code.value }, query: { e: eventId.value } })
 return result
})
watch(card, value => { if (!value) return; document.title = value.status === 'disabled' ? '该名片已停用' : `${value.name}｜${value.title}｜${value.company.short_name || value.company.name}`; if (value.status === 'active') void trackVisit() })
async function trackVisit() {
 const revision = ++visitRevision; const activeCode = code.value
 try { await visitor.ensure(); const source = ['nfc', 'qr', 'poster', 'link', 'sig'].includes(String(route.query.s)) ? String(route.query.s) as 'nfc' | 'qr' | 'poster' | 'link' | 'sig' : 'link'; const result = await createVisit({ body: { card_code: activeCode, source, campaign_id: eventId.value } }); if (revision === visitRevision) { visitId = result.visit_id; sessionStorage.setItem(sceneKey(activeCode, eventId.value, activeSource.value), String(result.visit_id)) } else await updateVisit({ path: { id: result.visit_id }, body: { stay_seconds: Math.min(86400, Math.floor((Date.now() - started) / 1000)) } }) }
 catch { trackingError.value = '访问记录暂未同步，浏览名片不受影响' }
}
function stay() { visitRevision++; if (visitId) { const id = visitId; visitId = undefined; void updateVisit({ path: { id }, body: { stay_seconds: Math.min(86400, Math.floor((Date.now() - started) / 1000)) } }).catch(() => { trackingError.value = '停留记录未同步' }) } }
window.addEventListener('pagehide', stay)
onUnmounted(() => { stay(); window.removeEventListener('pagehide', stay) })
function chat(question?: string) { router.push({ path: `/chat/${code.value}`, query: { ...sceneQuery(activeSource.value, eventId.value), ...(question ? { q: question } : {}) } }) }
watch([code, eventId, activeSource], () => { stay(); started = Date.now(); trackingError.value = ''; guide.value = false; void reload() })
function contact() { if (isWechat) guide.value = true; else saveContact(code.value) }
</script>
<template><ResourceState :loading="loading" :error="error" @retry="reload"><DisabledCard v-if="card?.status === 'disabled'" :company="card.company" /><main v-else-if="card" class="page immersive"><div class="page-body"><CardHero :card="card" :share-query="shareQuery" /><section v-if="card.campaign" class="event-banner"><span class="tag">展会交流</span><strong>{{ card.campaign.name }}</strong><span>{{ [card.campaign.location, card.campaign.booth].filter(Boolean).join(' · ') }}</span></section><div class="vc-sheet"><CardAiEntry :card="card" @chat="chat" /><DemoBadge class="vc-demo" /><div class="quick"><button v-if="card.mobile" @click="card.mobile && callPhone(card.mobile)"><i class="quick-ico"><span class="icon i-lucide-phone" /></i>打电话</button><button v-if="card.wechat_qr_url" @click="wechat = true"><i class="quick-ico"><span class="icon i-lucide-message-circle" /></i>加微信</button><button @click="contact"><i class="quick-ico"><span class="icon i-lucide-contact-round" /></i>存通讯录</button><button v-if="card.company.address" @click="card.company.address && openMap(card.company.address)"><i class="quick-ico"><span class="icon i-lucide-navigation" /></i>导航</button><button v-if="!card.wechat_qr_url" @click="copyText(`${origin}/c/${code}?s=${activeSource}${eventId ? `&e=${eventId}` : ''}`)"><i class="quick-ico"><span class="icon i-lucide-link" /></i>复制链接</button></div><CardDetails :card="card" @question="chat" /><p v-if="trackingError" class="muted small tracking-note">{{ trackingError }}</p><footer class="vc-foot">内容由{{ card.company.short_name || card.company.name }}官方维护<br>有合作意向？<button class="text-link" @click="router.push({ path: `/chat/${code}`, query: { ...sceneQuery(activeSource, eventId), lead: '1' } })">留下联系方式</button>，我会尽快联系您</footer></div></div><div class="vc-bar"><button v-if="card.mobile" class="mini" @click="callPhone(card.mobile)"><span class="icon i-lucide-phone" />电话</button><button v-if="card.wechat_qr_url" class="mini" @click="wechat = true"><span class="icon i-lucide-message-circle" />微信</button><van-button type="primary" class="vc-bar-cta" @click="chat()"><span class="icon i-lucide-message-square" />和TA聊聊</van-button></div><van-popup v-model:show="wechat" position="bottom" round closeable><div class="sheet stack"><h2>添加微信</h2><img v-if="card.wechat_qr_url" :src="card.wechat_qr_url" alt="员工微信二维码"><p class="muted">长按识别二维码添加微信</p></div></van-popup><van-overlay :z-index="30" :show="guide" @click="guide = false"><section class="wechat-guide" role="dialog" aria-label="在浏览器打开" @click.stop><span class="icon i-lucide-arrow-up-right wg-arrow" aria-hidden="true" /><h2>在浏览器中打开，即可存入通讯录</h2><p class="wg-lead">微信里无法直接保存联系人。点击右上角 <span class="wg-dots" aria-hidden="true"><i /><i /><i /></span>，选择「在浏览器打开」，再点“存通讯录”。</p><div v-if="card.mobile" class="wg-alt"><span class="wg-alt-lbl">也可以直接复制号码</span><div class="wg-alt-row"><b class="num">{{ card.mobile }}</b><van-button size="small" class="wg-copy" @click="copyText(card.mobile)">复制</van-button></div></div><div class="wg-ok"><van-button plain class="wg-ok-btn" @click="guide = false">知道了</van-button></div></section></van-overlay></main></ResourceState></template>
<style scoped>.page.immersive{padding-top:0;position:relative;min-height:100vh;display:flex;flex-direction:column}.page-body{flex:1;overflow-x:hidden;padding-bottom:96px}.event-banner{display:grid;gap:8px;padding:16px 20px 48px;background:var(--c-primary-soft);color:var(--c-ink)}.vc-sheet{position:relative;margin-top:-24px;background:var(--c-bg);border-radius:20px 20px 0 0;z-index:2;padding-top:16px;display:grid;gap:0}.vc-demo{margin:12px 16px 0}.quick{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:12px 16px 0;padding:14px 4px;background:var(--c-surface);border-radius:var(--r-lg)}.quick button{display:flex;flex-direction:column;align-items:center;gap:6px;border:0;padding:0;background:transparent;font-size:var(--fs-xs);color:var(--c-text-2);min-height:60px;cursor:pointer}.quick-ico{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;background:var(--c-primary-soft);color:var(--c-primary)}.quick-ico .icon{width:22px;height:22px}.tracking-note{padding:0 16px;margin-top:12px}.vc-foot{text-align:center;padding:24px 16px 20px;font-size:var(--fs-xs);color:var(--c-text-3)}.vc-foot .text-link{border:0;padding:0;background:transparent;color:var(--c-primary);cursor:pointer;font:inherit}.vc-bar{position:fixed;bottom:0;left:0;right:0;max-width:480px;margin:0 auto;z-index:10;display:flex;gap:8px;align-items:center;padding:10px 16px calc(28px + env(safe-area-inset-bottom));background:var(--c-bar-bg);backdrop-filter:blur(10px);border-top:1px solid var(--c-line)}.vc-bar .mini{display:flex;flex-direction:column;align-items:center;gap:1px;border:0;padding:0;background:transparent;font-size:10.5px;color:var(--c-text-2);width:48px;cursor:pointer}.vc-bar .mini .icon{width:20px;height:20px}.vc-bar-cta{flex:1}.vc-bar-cta .icon{width:18px;height:18px;margin-right:4px}.wechat-guide{padding:60px 28px;display:block;color:var(--c-surface)}.wechat-guide h2{color:var(--c-surface);font-size:var(--fs-lg);margin-top:8px}.wg-arrow{display:block;margin-left:auto;width:48px;height:48px}.wg-lead{margin-top:12px;font-size:var(--fs-sm);line-height:1.8;color:var(--c-on-ink-2)}.wg-dots{display:inline-flex;align-items:center;gap:3px;padding:2px 8px;border-radius:var(--r-pill);background:var(--c-on-ink-line);vertical-align:middle}.wg-dots i{width:4px;height:4px;border-radius:var(--r-pill);background:var(--c-surface)}.wg-alt{margin-top:28px;padding:16px;border-radius:var(--r-lg);background:var(--c-on-ink-line)}.wg-alt-lbl{font-size:var(--fs-sm);color:var(--c-on-ink-2)}.wg-alt-row{display:flex;align-items:center;justify-content:space-between;margin-top:8px}.wg-alt-row .num{font-size:20px;letter-spacing:.04em}.wg-copy{background:var(--c-surface);color:var(--c-ink);border-color:var(--c-surface)}.wg-ok{text-align:center;margin-top:36px}.wg-ok-btn{color:var(--c-surface);border-color:var(--c-on-ink-2);background:transparent}.sheet.stack{padding:var(--sp-5,20px);display:grid;gap:var(--sp-3,12px);justify-items:center}.sheet.stack img{max-width:220px}</style>
